class CrackSpec:
    __slots__ = ("points", "width", "phase", "intensity")

    def __init__(self, points, width, phase, intensity):
        self.points = points
        self.width = width
        self.phase = phase
        self.intensity = intensity


class CharSpec:
    __slots__ = ("x", "y", "rx", "ry", "color")

    def __init__(self, x, y, rx, ry, color):
        self.x = x
        self.y = y
        self.rx = rx
        self.ry = ry
        self.color = color


class DripSpec:
    __slots__ = ("x", "y", "length", "width", "phase", "speed")

    def __init__(self, x, y, length, width, phase, speed):
        self.x = x
        self.y = y
        self.length = length
        self.width = width
        self.phase = phase
        self.speed = speed


class SparkSpec:
    __slots__ = ("x", "y", "phase", "size")

    def __init__(self, x, y, phase, size):
        self.x = x
        self.y = y
        self.phase = phase
        self.size = size


