# GTK 3 / GTK 4 application
# ---------------------------------------------------------------------------

class _PrankWindow:
    """One fullscreen prank window and the drawing state for its monitor."""

    __slots__ = ("window", "area", "renderer", "renderer_size",
                 "renderer_failed", "geometry", "monitor", "primary",
                 "shortcut_surface", "shortcuts_inhibited")

    def __init__(self, window, monitor, geometry, primary):
        self.window = window
        self.area = None
        self.renderer = None
        self.renderer_size = None
        self.renderer_failed = False
        self.geometry = geometry
        self.monitor = monitor
        self.primary = primary
        self.shortcut_surface = None
        self.shortcuts_inhibited = False


class HyprlandShortcutLock:
    """Temporarily route every key to the prank on Hyprland.

    The keyboard-shortcuts-inhibit Wayland protocol is the portable way
    to ask a compositor to stop consuming Super/Alt shortcuts.  Hyprland
    honours it for window-management binds, but some Omarchy global
    binds (the root menu, for example) can still fire.  A Hyprland
    submap with only a harmless F24 binding disables every normal bind,
    so the focused prank window receives the keys instead.

    Runtime submap definitions are not persisted between hyprctl calls,
    therefore define and enter the submap in one eval.  A detached
    watchdog restores the previous submap if this process dies without
    running its cleanup.
    """

    WATCHDOG = r'''
import os
import subprocess
import sys
import time

parent = int(sys.argv[1])
hyprctl = sys.argv[2]
restore = sys.argv[3]
name = sys.argv[4]
while True:
    try:
        os.kill(parent, 0)
    except ProcessLookupError:
        break
    except PermissionError:
        pass
    time.sleep(0.25)
try:
    subprocess.run([hyprctl, "dispatch", restore],
                   stdout=subprocess.DEVNULL,
                   stderr=subprocess.DEVNULL,
                   timeout=3)
    current = subprocess.run([hyprctl, "submap"],
                             capture_output=True, text=True, timeout=2)
    if current.stdout.strip() == name:
        subprocess.run([hyprctl, "dispatch",
                        'hl.dsp.submap("reset")'],
                       stdout=subprocess.DEVNULL,
                       stderr=subprocess.DEVNULL,
                       timeout=3)
except Exception:
    pass
'''

    def __init__(self) -> None:
        self.debug = bool(os.environ.get("FAKE_RANSOM_DEBUG", "").strip())
        self.hyprctl = None
        self.available = False
        self.generation = 0
        self.name = ""
        self.previous = "default"
        self.entered = False
        self.last_check = 0.0
        self.watchdog = None
        if not os.environ.get("HYPRLAND_INSTANCE_SIGNATURE"):
            return
        self.hyprctl = shutil.which("hyprctl")
        if not self.hyprctl:
            if self.debug:
                print("hyprland submap: hyprctl not found", file=sys.stderr)
            return
        self.available = True

    # -- hyprctl helpers ---------------------------------------------------

    def _run(self, *args, timeout=3):
        if not self.hyprctl:
            return None
        try:
            return subprocess.run(
                [self.hyprctl] + list(args),
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                timeout=timeout,
                check=False,
            )
        except Exception:
            return None

    def _current_submap(self):
        if not self.hyprctl:
            return ""
        try:
            result = subprocess.run(
                [self.hyprctl, "submap"],
                capture_output=True, text=True, timeout=2, check=False)
        except Exception:
            return ""
        lines = [line.strip() for line in result.stdout.splitlines()
                 if line.strip()]
        return lines[-1] if lines else ""

    def _restore_expr(self):
        previous = self.previous
        if (not previous or previous == "default" or
                not re.fullmatch(r"[A-Za-z0-9_.-]{1,64}", previous)):
            return 'hl.dsp.submap("reset")'
        return 'hl.dsp.submap("%s")' % previous

    def _spawn_watchdog(self):
        if self.watchdog is not None and self.watchdog.poll() is None:
            return
        if not sys.executable:
            return
        try:
            self.watchdog = subprocess.Popen(
                [sys.executable, "-c", self.WATCHDOG, str(os.getpid()),
                 self.hyprctl, self._restore_expr(), self.name],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                stdin=subprocess.DEVNULL,
                start_new_session=True,
                close_fds=True,
            )
        except Exception as exc:
            self.watchdog = None
            if self.debug:
                print("hyprland submap: watchdog failed:", exc,
                      file=sys.stderr)

    # -- public API --------------------------------------------------------

    def engage(self, force=False):
        if not self.available:
            return False
        now = time.monotonic()
        if not force and now - self.last_check < 1.0:
            return self.entered
        self.last_check = now
        current = self._current_submap()
        if current == self.name:
            self.entered = True
            return True
        if (current and not current.startswith("fake_ransom_") and
                re.fullmatch(r"[A-Za-z0-9_.-]{1,64}", current)):
            # Remember where the user was before the prank took over.
            self.previous = current
        self.generation += 1
        name = "fake_ransom_%d_%d" % (os.getpid(), self.generation)
        self.name = name
        expression = (
            'hl.define_submap("%s", function() '
            'hl.bind("F24", hl.dsp.no_op()) end); '
            'hl.dispatch(hl.dsp.submap("%s"))' % (name, name)
        )
        self._run("eval", expression)
        if self._current_submap() != name:
            # A second dispatch is harmless and helps on builds where
            # the definition took effect but the inline dispatch did not.
            self._run("dispatch", 'hl.dsp.submap("%s")' % name)
        if self._current_submap() != name:
            if self.debug:
                print("hyprland submap: lock failed", file=sys.stderr)
            self.entered = False
            return False
        self.entered = True
        self._spawn_watchdog()
        if self.debug:
            print("hyprland submap locked (was %r)" % current,
                  file=sys.stderr)
        return True

    def ensure(self, force=False):
        if not self.available:
            return False
        now = time.monotonic()
        if not force and now - self.last_check < 1.0:
            return self.entered
        self.last_check = now
        if self.entered and self._current_submap() == self.name:
            return True
        if self.entered and self.debug:
            print("hyprland submap lost; re-entering", file=sys.stderr)
        return self.engage(force=True)

    def release(self):
        if not self.available or not self.name:
            return
        current = self._current_submap()
        reset_ok = True
        if current == self.name:
            self._run("dispatch", self._restore_expr())
            if self._current_submap() == self.name:
                self._run("dispatch", 'hl.dsp.submap("reset")')
            reset_ok = self._current_submap() != self.name
        self.entered = False
        self.last_check = 0.0
        if self.watchdog is not None:
            try:
                if reset_ok and self.watchdog.poll() is None:
                    self.watchdog.terminate()
            except Exception:
                pass
            if reset_ok:
                self.watchdog = None
        if reset_ok:
            self.name = ""
        if self.debug:
            print("hyprland submap released", file=sys.stderr)


class RansomApp:
    def __init__(self, args, version, Gtk, Gdk, Gio, GLib, Pango, PangoCairo):
        self.args = args
        self.version = version
        self.Gtk = Gtk
        self.Gdk = Gdk
        self.Gio = Gio
        self.GLib = GLib
        self.Pango = Pango
        self.PangoCairo = PangoCairo

        self.state = RansomState()
        self.start = time.monotonic()
        self.windows = []
        # Compatibility aliases for the primary window.
        self.window = None
        self.area = None
        self.timer_id = None
        self.cursor_timer_id = None
        self.blank_cursor = None
        self._seat = None
        self._grab_ticks = 0
        self._hyprland_lock = HyprlandShortcutLock()
        self.closing = False
        self.windowed = args.windowed_size is not None
        self.summoning = True

        self.app = Gtk.Application(
            application_id="com.bossdefender.fakeransom.static",
            flags=Gio.ApplicationFlags.FLAGS_NONE,
        )
        self.app.connect("activate", self._on_activate)
        self.app.connect("shutdown", self._on_shutdown)

    # -- window setup -------------------------------------------------------

    def _monitors(self):
        """Return ([(monitor, (x, y, width, height)), ...], primary_index).

        GTK 3 names a monitor by its GdkScreen index; GTK 4 needs the
        GdkMonitor object itself for fullscreen_on_monitor().  GTK 4 no
        longer exposes a primary-monitor query, so its first monitor is
        treated as primary, which matches the compositor's order.
        """
        result = []
        primary = 0
        try:
            with warnings.catch_warnings():
                warnings.simplefilter("ignore")
                if self.version == "4.0":
                    display = self.Gdk.Display.get_default()
                    monitors = display.get_monitors() if display else None
                    if monitors is not None:
                        for index in range(monitors.get_n_items()):
                            monitor = monitors.get_item(index)
                            geo = monitor.get_geometry()
                            if geo.width > 0 and geo.height > 0:
                                result.append(
                                    (monitor,
                                     (int(geo.x), int(geo.y),
                                      int(geo.width), int(geo.height))))
                else:
                    screen = self.Gdk.Screen.get_default()
                    if screen is not None:
                        primary_ref = screen.get_primary_monitor()
                        for index in range(screen.get_n_monitors()):
                            geo = screen.get_monitor_geometry(index)
                            if geo.width > 0 and geo.height > 0:
                                result.append(
                                    (index,
                                     (int(geo.x), int(geo.y),
                                      int(geo.width), int(geo.height))))
                        primary = next(
                            (pos for pos, item in enumerate(result)
                             if item[0] == primary_ref), 0)
        except Exception:
            result = []
            primary = 0
        if not result:
            return [(0, (0, 0, 1920, 1080))], 0
        if primary < 0 or primary >= len(result):
            primary = 0
        return result, primary

    def _monitor_geometry(self):
        monitors, primary = self._monitors()
        return monitors[primary][1]

    def _create_window(self, app, monitor, geometry, primary):
        win = self.Gtk.Window()
        win.set_application(app)
        win.set_title("Locked by BossDefender")
        win.set_decorated(False)
        win.set_resizable(False)
        try:
            win.set_modal(False)
        except Exception:
            pass

        if primary:
            try:
                win.set_can_focus(True)
            except Exception:
                pass
        else:
            # Display-only window: it must never take focus or keyboard
            # input.  The primary window owns the password and mirrors its
            # state here.
            try:
                if self.version == "3.0":
                    win.set_accept_focus(False)
                    win.set_focus_on_map(False)
                else:
                    win.set_focusable(False)
            except Exception:
                pass
            try:
                win.set_can_focus(False)
            except Exception:
                pass

        if self.windowed:
            width, height = self.args.windowed_size
            win.set_default_size(width, height)
        else:
            mx, my, mw, mh = geometry
            win.set_default_size(mw, mh)
            if self.version == "3.0":
                try:
                    win.move(mx, my)
                except Exception:
                    pass

        if self.version == "3.0":
            try:
                win.set_keep_above(True)
                win.set_skip_taskbar_hint(True)
                win.set_skip_pager_hint(True)
                win.set_urgency_hint(False)
            except Exception:
                pass

        rec = _PrankWindow(win, monitor, geometry, primary)
        area = self.Gtk.DrawingArea()
        rec.area = area
        if self.version == "4.0":
            area.set_draw_func(
                lambda widget, cr, width, height, r=rec: self._draw(
                    r, cr, int(width), int(height)))
            area.set_hexpand(True)
            area.set_vexpand(True)
            win.set_child(area)
        else:
            area.set_size_request(640, 480)
            area.connect(
                "draw",
                lambda widget, cr, r=rec: self._on_draw3(r, widget, cr))
            win.add(area)
            # GTK 3 does not reveal children automatically the way GTK 4
            # does.  Without this the DrawingArea stays hidden and the
            # window shows only the theme background.
            area.show()

        if self.version == "4.0":
            if primary:
                controller = self.Gtk.EventControllerKey.new()
                controller.set_propagation_phase(
                    self.Gtk.PropagationPhase.CAPTURE)
                controller.connect("key-pressed", self._on_key4)
                win.add_controller(controller)
            win.connect("close-request", self._on_close_request)
            win.connect(
                "notify::fullscreened",
                lambda window, pspec, r=rec:
                self._on_fullscreen_changed4(r, window, pspec))
        else:
            if primary:
                win.connect("key-press-event", self._on_key3)
                win.connect(
                    "realize",
                    lambda window, r=rec: self._on_realize3(r, window))
            win.connect("delete-event", self._on_delete_event)
            win.connect(
                "window-state-event",
                lambda window, event, r=rec:
                self._on_window_state3(r, window, event))

        for widget in (win, area):
            if widget is None:
                continue
            try:
                widget.connect("map", lambda w, r=rec: self._on_map(r))
            except Exception:
                pass
        if primary:
            try:
                win.connect(
                    "notify::is-active",
                    lambda window, pspec, r=rec:
                    self._on_active_changed(r, window, pspec))
            except Exception:
                pass
        return rec

    def _build_windows(self, app):
        monitors, primary_index = self._monitors()
        if self.windowed:
            monitors = [monitors[primary_index]]
            primary_index = 0
        for index, (monitor, geometry) in enumerate(monitors):
            rec = self._create_window(
                app, monitor, geometry, index == primary_index)
            self.windows.append(rec)
            if rec.primary:
                self.window = rec.window
                self.area = rec.area

        if self.window is None:
            # Defensive fallback: there must always be one window that can
            # take keyboard input.
            rec = self._create_window(app, 0, (0, 0, 1920, 1080), True)
            self.windows.append(rec)
            self.window = rec.window
            self.area = rec.area

    def _show_window(self, rec, activate):
        try:
            if self.version == "3.0":
                rec.window.show_all()
            if activate:
                rec.window.present()
                try:
                    rec.window.grab_focus()
                except Exception:
                    pass
            elif self.version == "4.0":
                rec.window.set_visible(True)
        except Exception:
            pass

    def _show_windows(self):
        if not self.windowed:
            for rec in self.windows:
                self._fullscreen_on(rec)
        # Map the display-only windows first and the primary last, so the
        # window manager gives the keyboard focus to the primary window.
        for rec in self.windows:
            if not rec.primary:
                self._show_window(rec, False)
        for rec in self.windows:
            if rec.primary:
                self._show_window(rec, True)

    def _primary_window(self):
        for rec in self.windows:
            if rec.primary:
                return rec
        return None

    def _focus_primary(self):
        rec = self._primary_window()
        if rec is None:
            return
        try:
            rec.window.present()
            rec.window.grab_focus()
        except Exception:
            pass
        self._refullscreen()

    def _fullscreen_on(self, rec):
        if self.windowed or rec.window is None:
            return
        try:
            if self.version == "3.0":
                screen = self.Gdk.Screen.get_default()
                if screen is not None:
                    rec.window.fullscreen_on_monitor(screen, rec.monitor)
                else:
                    rec.window.fullscreen()
            else:
                rec.window.fullscreen_on_monitor(rec.monitor)
        except Exception:
            try:
                rec.window.fullscreen()
            except Exception:
                pass

    def _on_activate(self, app):
        if self.windows:
            self._focus_primary()
            return

        self._build_windows(app)
        self._show_windows()
        self.GLib.timeout_add(
            int(SUMMONING_SECONDS * 1000.0), self._summoning_done)

        if not self.windowed:
            self.GLib.idle_add(self._hyprland_lock.engage)
        if self.version == "4.0":
            self.GLib.idle_add(self._inhibit_system_shortcuts)
        self.GLib.idle_add(self._hide_cursor)
        if self.version == "3.0":
            self.GLib.idle_add(self._grab_keyboard)
        if not self.windowed:
            self.GLib.idle_add(self._refullscreen)

        # No frame timer: the still wallpaper is painted once.  This
        # low-frequency watchdog re-asserts fullscreen and notices when
        # the 2.4 s ACCESS DENIED banner expires, then repaints once.
        self._last_denied = False
        self._settle_ticks = 0
        self.timer_id = self.GLib.timeout_add(250, self._on_watch)
        # Re-assert the invisible cursor once a second.  Some compositors
        # replace the cursor when the pointer enters a newly mapped surface.
        self.cursor_timer_id = self.GLib.timeout_add(1000, self._cursor_tick)

        if self.args.duration and self.args.duration > 0:
            self.GLib.timeout_add(
                int(self.args.duration * 1000.0), self._duration_done)
        if self.args.autotype:
            self.GLib.timeout_add(
                int(SUMMONING_SECONDS * 1000.0) + 400, self._autotype)

    # -- drawing ------------------------------------------------------------

    def _queue_draw(self, rec=None):
        targets = self.windows if rec is None else (rec,)
        for item in targets:
            if item.area is not None:
                try:
                    item.area.queue_draw()
                except Exception:
                    pass

    def _draw(self, rec, cr, width, height):
        if width <= 0 or height <= 0:
            return
        if rec.renderer_failed:
            cr.set_source_rgba(0.0, 0.0, 0.0, 1.0)
            cr.paint()
            return
        try:
            if self.summoning:
                draw_summoning(
                    cr, float(width), float(height),
                    self.Pango, self.PangoCairo)
                return
            if rec.renderer is None or rec.renderer_size != (width, height):
                rec.renderer = RansomRenderer(
                    width, height, self.Pango, self.PangoCairo)
                rec.renderer_size = (width, height)
            rec.renderer.draw(
                cr, time.monotonic(),
                self.state.typed, self.state.denied_until)
        except Exception:
            rec.renderer_failed = True
            traceback.print_exc()
            cr.set_source_rgba(0.02, 0.0, 0.0, 1.0)
            cr.paint()

    def _on_draw3(self, rec, area, cr):
        alloc = area.get_allocation()
        self._draw(rec, cr, int(alloc.width), int(alloc.height))
        return False

    # -- input --------------------------------------------------------------

    def _modifier_mask(self):
        # GTK 3 exposes Alt as MOD1_MASK; GTK 4 renamed it ALT_MASK.
        # Look both up defensively so the same code works on either.
        mods = self.Gdk.ModifierType.CONTROL_MASK
        for name in ("ALT_MASK", "MOD1_MASK",
                     "SUPER_MASK", "META_MASK", "HYPER_MASK"):
            mods |= getattr(self.Gdk.ModifierType, name, 0)
        return mods

    def _handle_key(self, keyval, state):
        if self.closing:
            return True
        debug = bool(os.environ.get("FAKE_RANSOM_DEBUG", "").strip())
        if debug:
            print("key keyval=%d state=0x%x" % (keyval, int(state)),
                  file=sys.stderr)
        meta_keys = (getattr(self.Gdk, "KEY_Super_L", 0),
                     getattr(self.Gdk, "KEY_Super_R", 0),
                     getattr(self.Gdk, "KEY_Meta_L", 0),
                     getattr(self.Gdk, "KEY_Meta_R", 0))
        if keyval and keyval in meta_keys:
            if os.environ.get("FAKE_RANSOM_DEBUG", "").strip():
                print("meta key reached the prank and was swallowed",
                      file=sys.stderr)
            return True
        if state & self._modifier_mask():
            return True

        if keyval in (self.Gdk.KEY_Return, self.Gdk.KEY_KP_Enter,
                      getattr(self.Gdk, "KEY_ISO_Enter", self.Gdk.KEY_Return)):
            if self.state.enter(time.monotonic()):
                self._exit_prank()
            else:
                self._queue_draw()
            return True

        if keyval == getattr(self.Gdk, "KEY_BackSpace", 0xFF08):
            self.state.backspace()
            self._queue_draw()
            return True

        codepoint = self.Gdk.keyval_to_unicode(keyval)
        if codepoint <= 0 or codepoint > 0x10FFFF:
            return True
        ch = chr(codepoint)
        # Only ASCII letters and digits may enter the password.  Space,
        # punctuation and every other character is ignored.
        if not (("a" <= ch <= "z") or ("A" <= ch <= "Z") or
                ("0" <= ch <= "9")):
            return True
        self.state.type_char(ch)
        if debug:
            print("typed %r -> %r" % (ch, self.state.typed), file=sys.stderr)
        self._queue_draw()
        return True

    def _on_key4(self, controller, keyval, keycode, state):
        return self._handle_key(keyval, state)

    def _on_key3(self, widget, event):
        return self._handle_key(event.keyval, event.state)

    # -- keyboard grab (X11 only) -----------------------------------------

    def _is_x11(self):
        try:
            name = self.Gdk.Display.get_default().get_name() or ""
        except Exception:
            return False
        return not name.lower().startswith("wayland")

    def _grab_keyboard(self):
        """Hold an X11 keyboard grab so the WM sees no Super/Alt+Tab.

        Wayland has no client-side keyboard grab and GTK 4 removed the
        API, so this only applies to GTK 3 on X11.  Elsewhere the app
        still filters every key it receives.
        """
        rec = self._primary_window()
        if (self.version != "3.0" or rec is None or
                self.closing or self.windowed or not self._is_x11()):
            if os.environ.get("FAKE_RANSOM_DEBUG", "").strip():
                print("keyboard grab: not available on this backend",
                      file=sys.stderr)
            return False

        try:
            display = self.Gdk.Display.get_default()
            seat = display.get_default_seat() if display is not None else None
            gdk_window = rec.window.get_window()
            if seat is not None and gdk_window is not None:
                status = seat.grab(
                    gdk_window,
                    self.Gdk.SeatCapabilities.KEYBOARD |
                    self.Gdk.SeatCapabilities.POINTER,
                    False, None, None, None, None,
                )
                if os.environ.get("FAKE_RANSOM_DEBUG", "").strip():
                    print("keyboard grab:", status, file=sys.stderr)
                if status == self.Gdk.GrabStatus.SUCCESS:
                    self._seat = seat
        except Exception:
            self._seat = None
        return False

    def _release_keyboard(self):
        if self._seat is not None:
            try:
                self._seat.ungrab()
            except Exception:
                pass
            self._seat = None

    # -- Wayland compositor shortcuts (GTK 4.16+) --------------------------

    def _inhibit_system_shortcuts(self, rec=None):
        """Ask the compositor not to consume Super/Meta/Alt+Tab.

        On Wayland the compositor handles those keys before a client
        sees them, so filtering in _handle_key is not enough.  GTK 4.16
        added Gdk.Toplevel.inhibit_system_shortcuts(), backed by the
        keyboard-shortcuts-inhibit Wayland protocol.  GTK 3 has no such
        API; on X11 the seat grab above already stops the window
        manager from acting on those keys.
        """
        if self.closing or self.version != "4.0":
            return False
        targets = self.windows if rec is None else (rec,)
        debug = bool(os.environ.get("FAKE_RANSOM_DEBUG", "").strip())
        for item in targets:
            try:
                surface = item.window.get_surface()
            except Exception:
                surface = None
            if surface is None:
                continue
            if not hasattr(surface, "inhibit_system_shortcuts"):
                if debug:
                    print("system shortcuts: this GTK cannot inhibit them",
                          file=sys.stderr)
                continue
            # The compositor may revoke the inhibitor when the surface
            # loses focus.  Check the live property instead of trusting
            # the fact that a request was sent once: if it is no longer
            # active, ask again on this focus/map/watchdog pass.
            granted = item.shortcuts_inhibited
            try:
                granted = bool(
                    surface.get_property("shortcuts-inhibited"))
            except Exception:
                pass
            if (item.shortcuts_inhibited and
                    item.shortcut_surface is surface and granted):
                continue
            try:
                surface.inhibit_system_shortcuts(None)
                item.shortcut_surface = surface
                item.shortcuts_inhibited = True
                if debug:
                    print("system shortcuts inhibit requested (was %r)"
                          % granted, file=sys.stderr)
            except Exception as exc:
                if debug:
                    print("system shortcuts inhibit failed:", exc,
                          file=sys.stderr)
        return False

    def _restore_system_shortcuts(self):
        self._hyprland_lock.release()
        for item in self.windows:
            surface = item.shortcut_surface
            item.shortcut_surface = None
            item.shortcuts_inhibited = False
            if surface is None:
                continue
            try:
                surface.restore_system_shortcuts()
            except Exception:
                pass

    # -- close / fullscreen / cursor ---------------------------------------

    def _block_close(self):
        if self.state.allow_close:
            return False
        self.state.deny(time.monotonic())
        self._queue_draw()
        return True

    def _on_close_request(self, window):
        return self._block_close()

    def _on_delete_event(self, window, event):
        return self._block_close()

    def _refullscreen(self):
        if self.closing or self.windowed:
            return False
        for rec in list(self.windows):
            try:
                if rec.window is not None and not rec.window.is_fullscreen():
                    self._fullscreen_on(rec)
                    if self.version == "3.0":
                        rec.window.set_keep_above(True)
            except Exception:
                pass
        rec = self._primary_window()
        if rec is not None:
            try:
                rec.window.present()
            except Exception:
                pass
        self._grab_keyboard()
        self._inhibit_system_shortcuts()
        return False

    def _on_fullscreen_changed4(self, rec, window, pspec):
        if self.closing or self.windowed:
            return
        try:
            if not window.is_fullscreen():
                self.GLib.idle_add(self._refullscreen)
        except Exception:
            pass

    def _on_window_state3(self, rec, window, event):
        if self.closing or self.windowed:
            return False
        try:
            if event.new_window_state & self.Gdk.WindowState.ICONIFIED:
                window.deiconify()
                self._fullscreen_on(rec)
                if rec.primary:
                    window.present()
            elif not (event.new_window_state & self.Gdk.WindowState.FULLSCREEN):
                self.GLib.idle_add(self._refullscreen)
        except Exception:
            pass
        return False

    def _cursor(self):
        if self.blank_cursor is not None:
            return self.blank_cursor

        display = self.Gdk.Display.get_default()
        if display is None:
            return None

        # A fully transparent cursor is more reliable than the "none" cursor
        # name, which is missing from many cursor themes (and whose GTK 4
        # constructor signature differs from GTK 3).
        try:
            import gi
            gi.require_version("GdkPixbuf", "2.0")
            from gi.repository import GdkPixbuf
            pixbuf = GdkPixbuf.Pixbuf.new(
                GdkPixbuf.Colorspace.RGB, True, 8, 32, 32)
            pixbuf.fill(0x00000000)
            if self.version == "4.0":
                with warnings.catch_warnings():
                    warnings.simplefilter("ignore", DeprecationWarning)
                    texture = self.Gdk.Texture.new_for_pixbuf(pixbuf)
                cursor = self.Gdk.Cursor.new_from_texture(texture, 0, 0)
            else:
                cursor = self.Gdk.Cursor.new_from_pixbuf(
                    display, pixbuf, 0, 0)
            if cursor is not None:
                self.blank_cursor = cursor
                return cursor
        except Exception:
            pass

        # Fallbacks.  GTK 4 takes (name, fallback); GTK 3 takes
        # (display, name).  Use the correct signature for each.
        try:
            if self.version == "4.0":
                cursor = self.Gdk.Cursor.new_from_name("none", None)
            else:
                cursor = self.Gdk.Cursor.new_from_name(display, "none")
            if cursor is not None:
                self.blank_cursor = cursor
                return cursor
        except Exception:
            pass
        return None

    def _apply_cursor(self, cursor, rec=None) -> None:
        targets = self.windows if rec is None else (rec,)
        for item in targets:
            window = item.window
            if window is None:
                continue
            try:
                if self.version == "4.0":
                    window.set_cursor(cursor)
                    if item.area is not None:
                        item.area.set_cursor(cursor)
                else:
                    for widget in (window, item.area):
                        if widget is None:
                            continue
                        gdk_window = widget.get_window()
                        if gdk_window is not None:
                            gdk_window.set_cursor(cursor)
            except Exception:
                pass

    def _hide_cursor(self):
        cursor = self._cursor()
        if cursor is not None:
            self._apply_cursor(cursor)

    def _show_cursor(self):
        self._apply_cursor(None)

    def _on_map(self, rec):
        self.GLib.idle_add(self._hide_cursor)
        if rec.primary and self.version == "3.0":
            self.GLib.idle_add(self._grab_keyboard)
        if self.version == "4.0":
            self.GLib.idle_add(self._inhibit_system_shortcuts, rec)
        if rec.primary and not self.windowed:
            self.GLib.idle_add(self._hyprland_lock.engage)
        self._queue_draw(rec)

    def _on_active_changed(self, rec, window, pspec):
        try:
            if window.is_active():
                self.GLib.idle_add(self._hide_cursor)
                self.GLib.idle_add(self._inhibit_system_shortcuts, rec)
                if not self.windowed:
                    self.GLib.idle_add(self._hyprland_lock.ensure, True)
                self.GLib.idle_add(self._refullscreen)
            elif not self.closing and not self.windowed:
                # A display-only window was clicked.  Put the keyboard
                # focus straight back on the primary window.
                self.GLib.timeout_add(80, self._refocus_primary)
        except Exception:
            pass

    def _refocus_primary(self):
        if self.closing or self.windowed:
            return False
        rec = self._primary_window()
        if rec is not None:
            try:
                rec.window.present()
                rec.window.grab_focus()
            except Exception:
                pass
        self._grab_keyboard()
        self._inhibit_system_shortcuts()
        self._hyprland_lock.ensure(True)
        return False

    def _cursor_tick(self):
        if self.closing:
            return False
        self._hide_cursor()
        return True

    def _on_realize3(self, rec, window):
        self._hide_cursor()
        if not rec.primary:
            return
        try:
            window.grab_focus()
        except Exception:
            pass
        if rec.area is not None:
            try:
                rec.area.grab_focus()
            except Exception:
                pass

    # -- timers / exit ------------------------------------------------------

    def _summoning_done(self):
        if self.closing:
            return False
        self.summoning = False
        self._queue_draw()
        return False

    def _on_watch(self):
        if self.closing:
            return False

        # Nudge the first frames after mapping.  Some window managers and
        # drivers hand out a zero-sized drawable for the first paint; a
        # few retries cost nothing and then stop for good.
        if self._settle_ticks < 8:
            self._settle_ticks += 1
            self._queue_draw()

        # Repaint only when the denial banner appears or expires, so the
        # wallpaper stays perfectly still in between.
        denied_now = self.state.denied
        if denied_now != self._last_denied:
            self._last_denied = denied_now
            self._queue_draw()

        if not self.windowed:
            for rec in list(self.windows):
                try:
                    if not rec.window.is_fullscreen():
                        self._fullscreen_on(rec)
                        if self.version == "3.0":
                            rec.window.set_keep_above(True)
                except Exception:
                    pass

            # Re-assert the X11 keyboard/pointer grab about once a second
            # (the watchdog runs every 250 ms).
            self._grab_ticks += 1
            if self._grab_ticks >= 4:
                self._grab_ticks = 0
                self._grab_keyboard()
                self._inhibit_system_shortcuts()
            if not self.windowed:
                self._hyprland_lock.ensure()
        return True

    def _duration_done(self):
        if not self.closing:
            print("fake_static_ransom_lin: duration reached", file=sys.stderr)
            self._exit_prank()
        return False

    def _autotype(self):
        if self.closing:
            return False
        now = time.monotonic()
        for ch in self.args.autotype:
            if ch in "\r\n":
                if self.state.enter(now):
                    self._exit_prank()
                    return False
            else:
                self.state.type_char(ch)
        if not self.closing:
            if self.state.enter(now):
                print("fake_static_ransom_lin: autotype unlocked", file=sys.stderr)
                self._exit_prank()
            else:
                print("fake_static_ransom_lin: autotype denied", file=sys.stderr)
                self._queue_draw()
        return False

    def _exit_prank(self):
        if self.closing:
            return
        self.closing = True
        self.state.allow_close = True
        self._restore_system_shortcuts()
        self._release_keyboard()
        self._show_cursor()
        if self.timer_id is not None:
            try:
                self.GLib.source_remove(self.timer_id)
            except Exception:
                pass
            self.timer_id = None
        if self.cursor_timer_id is not None:
            try:
                self.GLib.source_remove(self.cursor_timer_id)
            except Exception:
                pass
            self.cursor_timer_id = None
        for rec in self.windows:
            try:
                rec.window.destroy()
            except Exception:
                pass
        self.windows = []
        self.window = None
        self.area = None
        try:
            self.app.quit()
        except Exception:
            pass

    def _on_shutdown(self, app):
        self._restore_system_shortcuts()
        self._release_keyboard()
        self._show_cursor()
        for attr in ("timer_id", "cursor_timer_id"):
            source_id = getattr(self, attr, None)
            if source_id is not None:
                try:
                    self.GLib.source_remove(source_id)
                except Exception:
                    pass
                setattr(self, attr, None)

    def run(self):
        return self.app.run([sys.argv[0]])

# ---------------------------------------------------------------------------
# Headless render test and self test
# ---------------------------------------------------------------------------

def run_render_test(args) -> int:
    if cairo is None:
        print("fake_static_ransom_lin.py needs pycairo for --render-test", file=sys.stderr)
        return 1
    Pango, PangoCairo = load_pango()
    width = max(320, int(args.width))
    height = max(240, int(args.height))
    try:
        renderer = RansomRenderer(width, height, Pango, PangoCairo)
        surface = cairo.ImageSurface(cairo.FORMAT_ARGB32, width, height)
        ctx = cairo.Context(surface)
        ctx.set_antialias(cairo.ANTIALIAS_BEST)
        now = time.monotonic()
        denied_until = now + 10.0 if args.denied else 0.0
        renderer.draw(ctx, now, args.typed or "", denied_until,
                      max(0.0, float(args.time)))
        surface.write_to_png(args.render_test)
    except Exception:
        traceback.print_exc()
        return 1
    print(args.render_test)
    return 0


def run_selftest() -> int:
    failures = 0

    def check(label, ok, detail=""):
        nonlocal failures
        if ok:
            print("PASS " + label)
        else:
            failures += 1
            print("FAIL " + label + (("  [" + detail + "]") if detail else ""))

    state = RansomState()
    check("empty does not match", not state.matches())
    state.type_char("b")
    state.type_char("o")
    state.type_char("m")
    state.type_char("b")
    state.type_char("o")
    check("typing", state.typed == "bombo", state.typed)
    state.backspace()
    check("backspace", state.typed == "bomb", state.typed)
    for ch in "oclat":
        state.type_char(ch)
    check("full passphrase", state.typed == "bomboclat", state.typed)
    check("passphrase matches", state.matches())
    check("correct enter unlocks", state.enter(time.monotonic()))
    check("closing flag", state.closing and state.allow_close)

    state = RansomState()
    for _ in range(20):
        state.type_char("x")
    check("max input length", len(state.typed) == MAX_INPUT_LENGTH,
          str(len(state.typed)))
    now = time.monotonic()
    state = RansomState()
    state.type_char("w")
    check("wrong enter denied", not state.enter(now))
    check("wrong enter clears", state.typed == "")
    check("wrong enter denies for 2.4s", state.denied_until > now)

    state = RansomState()
    for ch in "  BoMbOcLaT  ":
        state.type_char(ch)
    check("trim + case match", state.matches(), state.typed)

    state = RansomState()
    state.type_char("\t")
    state.type_char("\n")
    check("control chars ignored", state.typed == "")

    for w, h in ((1920, 1080), (2560, 1440), (1366, 768), (1920, 1200),
                 (3440, 1440), (2560, 1080), (1080, 1920), (800, 1280),
                 (1024, 768), (1600, 980)):
        m = adaptive_metrics(w, h)
        skx, sky, skw, skh = m["skull"]
        cpx, cpy, cpw, cph = m["cap"]
        vis = SKULL_DIAMETER * skh
        cyc = sky + SKULL_CENTER * skh
        check("caption at bottom %dx%d" % (w, h),
              0.0 <= cpy and cpy + cph <= h + 1.0)
        check("caption centred %dx%d" % (w, h),
              abs(cpx + cpw / 2.0 - w / 2.0) < 1.0)
        check("caption fits width %dx%d" % (w, h),
              cpx >= -1.0 and cpx + cpw <= w + 1.0)
        check("visible skull fits width %dx%d" % (w, h), vis <= w + 1.0)
        check("visible skull fits height %dx%d" % (w, h),
              cyc - vis / 2.0 >= -1.0 and cyc + vis / 2.0 <= h + 1.0)
        check("skull centred %dx%d" % (w, h),
              abs(skx + skw / 2.0 - w / 2.0) < 1.0)
        check("16:9 detection %dx%d" % (w, h),
              is_16_9(w, h) == (abs(w / float(h) - 16.0 / 9.0) <= 0.012))

    print("== done: " + ("ALL PASS" if failures == 0 else
                         str(failures) + " FAILURE(S)") + " ==")
    return 0 if failures == 0 else 1


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def parse_windowed(value):
    if value is None:
        return None
    if value is True or value == "":
        return (1280, 720)
    text = str(value).lower().replace(" ", "")
    if "x" not in text:
        raise ValueError("expected WxH")
    w_text, h_text = text.split("x", 1)
    width = int(w_text)
    height = int(h_text)
    if width < 320 or height < 240:
        raise ValueError("window must be at least 320x240")
    return (width, height)


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(
        prog="fake_static_ransom_lin.py",
        description="Static Linux fake-ransomware prank (keyboard only, no animation).",
    )
    parser.add_argument("--selftest", action="store_true",
                        help="test password logic without opening a window")
    parser.add_argument("--render-test", metavar="PNG",
                        help="render one frame to a PNG and exit")
    parser.add_argument("--width", type=int, default=1920,
                        help="render-test width (default 1920)")
    parser.add_argument("--height", type=int, default=1080,
                        help="render-test height (default 1080)")
    parser.add_argument("--typed", default="",
                        help="pre-filled typed text for --render-test")
    parser.add_argument("--denied", action="store_true",
                        help="show ACCESS DENIED for --render-test")
    parser.add_argument("--time", type=float, default=0.5,
                        help="frozen frame time for --render-test (default 0.5)")
    parser.add_argument("--windowed", nargs="?", const="1280x720",
                        metavar="WxH",
                        help="run in a normal window instead of fullscreen")
    parser.add_argument("--duration", type=float, default=0.0,
                        help="auto-exit after N seconds (testing)")
    parser.add_argument("--autotype", default="",
                        help="type this text after 1s (testing)")
    args = parser.parse_args(argv)

    try:
        args.windowed_size = parse_windowed(args.windowed)
    except ValueError as exc:
        parser.error("--windowed: " + str(exc))

    if args.selftest:
        return run_selftest()
    if args.render_test:
        return run_render_test(args)

    version, Gtk, Gdk, Gio, GLib, Pango, PangoCairo = load_gtk()
    app = RansomApp(args, version, Gtk, Gdk, Gio, GLib, Pango, PangoCairo)
    return app.run()


if __name__ == "__main__":
    raise SystemExit(main())
